/* Hall records use recorded simulation careers only. No pre-save achievements are invented. */
function hallState(){return state.hallOfFame??={version:1,people:[],classes:[]}}
function hallPerson(key,name,kind){const h=hallState();let p=h.people.find(p=>p.key===key);if(!p){p={key,name,kind,seasons:[],retired:null,inducted:null,votes:[]};h.people.push(p);if(kind==='Player'){const id=Number(key.slice(2));for(const r of state.statsArchive||[])if(r.id===id&&!p.seasons.some(s=>s.year===r.year)){const a=(state.regularAwards||[]).find(a=>a.year===r.year)||(state.leagueHistory||[]).find(a=>a.year===r.year)||{};p.seasons.push({year:r.year,team:r.team,age:r.age||0,gp:r.gp||0,pts:r.pts||0,reb:r.reb||0,ast:r.ast||0,peak:r.gp?r.pts/r.gp:0,mvp:a.mvp?.name===name?1:0,dpoy:a.dpoy?.name===name?1:0});}}}return p}
function hallScore(p){const s=p.seasons,tot=k=>s.reduce((n,r)=>n+(Number(r[k])||0),0),awards=tot('mvp')*10+tot('finalsMvp')*8+tot('firstTeam')*4+tot('titles')*5+tot('dpoy')*5+tot('coy')*5,longevity=p.kind==='Player'?s.length>=15&&tot('gp')>=900&&(tot('pts')>=20000||tot('reb')>=12000||tot('ast')>=10000):s.length>=15&&tot('w')>=750,peak=tot('mvp')>=2&&tot('titles')>=2,ws=s.length>0&&s.every(r=>Number.isFinite(r.ws))?tot('ws'):null,automatic=awards>=35||longevity||peak||ws>=100&&ws!==null;const pct=automatic?100:Math.min(95,Math.round(awards/35*65+Math.min(20,tot('pts')/1000)+Math.min(10,s.length/2)));return {awards,longevity,peak,ws,automatic,pct,tot}}
function hallCapture(){
 const year=state.year,honors=seasonHonors(),regular=(state.regularAwards||[]).find(r=>r.year===year)||honors||{},snap=statsSnapshot(),all=[...state.teams.flatMap(t=>t.roster),...state.free];
 for(const p of all){const h=hallPerson('p:'+p.id,p.name,'Player');if(h.seasons.some(r=>r.year===year))continue;const r=snap.find(r=>r.id===p.id),club=state.teams.find(t=>t.roster.some(q=>q.id===p.id)),abbr=r?.team||club?.abbr||'FA',champ=state.teams[state.champion],honor=k=>regular[k]?.name===p.name&&(!club||regular[k]?.team===club.city+' '+club.name)?1:0;
 h.seasons.push({year,team:abbr,age:p.age,gp:r?.gp||0,pts:r?.pts||0,reb:r?.reb||0,ast:r?.ast||0,peak:r?.gp?r.pts/r.gp:0,mvp:honor('mvp'),dpoy:honor('dpoy'),finalsMvp:honors?.finalsMvp?.name===p.name?1:0,titles:club===champ&&state.history.some(g=>g.stage!=='Regular season'&&g.box.some(b=>b.playerId===p.id&&b.mp>0))?1:0});}
 for(const t of state.teams){const c=coachFor(t),h=hallPerson('c:'+t.key+':'+c.name,c.name,'Coach');if(!h.seasons.some(r=>r.year===year))h.seasons.push({year,team:t.abbr,w:t.w,l:t.l,titles:t.id===state.champion?1:0,coy:regular.coach?.name===c.name?1:0});}
 gmCaptureHall();
}
function hallVote(p,year){const score=hallScore(p);if(score.automatic)return 100;let seed=year;for(const c of p.key)seed=(Math.imul(seed,31)+c.charCodeAt(0))>>>0;const media=score.awards/35*100,players=Math.min(100,score.tot('titles')*15+score.tot('mvp')*20+score.pct*.4),stats=score.pct;return Math.max(0,Math.min(99,Math.round(media*.35+players*.25+stats*.4+(seed%21)-10+Math.min(10,Math.max(0,year-p.retired-8)))))}
function hallRollover(){const h=hallState();for(const t of state.teams){const retiring=t.roster.filter(p=>p.age>=38&&(p.age>=43||Math.random()<.12+(p.age-38)*.07)).slice(0,Math.max(0,t.roster.length-rosterMinimum()));for(const p of retiring){const r=hallPerson('p:'+p.id,p.name,'Player');r.retired=state.year;t.roster=t.roster.filter(q=>q.id!==p.id);say(p.name+' retires after '+r.seasons.length+' recorded seasons. Hall eligibility: '+(state.year+3)+'.')}if(retiring.length)delete t.rotationPlan;}
 const active=new Set([...state.teams.flatMap(t=>t.roster),...state.free].map(p=>'p:'+p.id));for(const p of h.people)if(p.kind==='Player'&&!active.has(p.key)&&p.retired===null&&(p.seasons.at(-1)?.age||0)>=35)p.retired=state.year;
 for(const t of state.teams){const c=coachFor(t);if(c.age>=75){hallPerson('c:'+t.key+':'+c.name,c.name,'Coach').retired=state.year;say(c.name+' retires from coaching.');t.coach=generateCoach({...t,key:t.key+':'+state.year});t.coach.age=45;coachFor(t)}}
 const coaches=new Set(state.teams.map(t=>'c:'+t.key+':'+coachFor(t).name));for(const p of h.people)if(p.kind==='Coach'&&!coaches.has(p.key)&&p.retired===null)p.retired=state.year;
 if(h.classes.some(c=>c.year===state.year))return;const inductees=[];for(const p of h.people){if(p.inducted!==null)continue;const eligible=p.kind==='Builder'?p.seasons.length>=20:p.retired!==null&&state.year-p.retired>=3;if(!eligible)continue;const vote=hallVote(p,state.year);p.votes.push({year:state.year,percent:vote});if(vote>=75){p.inducted=state.year;inductees.push(p.key)}}h.classes.push({year:state.year,people:inductees});say('Hall of Fame Class of '+state.year+': '+(inductees.length?inductees.map(k=>h.people.find(p=>p.key===k).name).join(', '):'No inductees this year.') );}
function hallSignature(p){const teams={};for(const r of p.seasons)teams[r.team]=(teams[r.team]||0)+(r.gp||r.w||1);return Object.keys(teams).sort((a,b)=>teams[b]-teams[a])[0]||'—'}
function hallFranchiseHonors(p){const groups={};for(const r of p.seasons)(groups[r.team]??=[]).push(r);return Object.entries(groups).filter(([t,s])=>t!=='FA'&&s.length>=5&&s.reduce((n,r)=>n+(r.gp||0),0)>=300&&s.reduce((n,r)=>n+(r.pts||0),0)>=8000).map(([t,s])=>t+' · '+(s.length>=10&&s.reduce((n,r)=>n+(r.pts||0),0)>=15000?'Jersey retirement honor':'Ring of Honor'))}
let hallFilter='Inductees';function hallSetFilter(v){hallFilter=v;render()}
function hallOfFameView(){const h=hallState(),people=(typeof hallPagePeople==='function'?hallPagePeople(h.people):h.people).filter(p=>hallFilter==='Inductees'?p.inducted!==null:hallFilter==='Eligible'?p.inducted===null&&p.retired!==null&&state.year-p.retired>=3:hallFilter==='Franchise honors'?hallFranchiseHonors(p).length: p.inducted===null).sort((a,b)=>hallScore(b).awards-hallScore(a).awards);return `<section class="panel"><div class="panelhead"><h2>Basketball Hall of Fame</h2><span>Legacies across generations</span></div><div class="note actions">${['Inductees','Eligible','Watchlist','Franchise honors'].map(v=>`<button class="${hallFilter===v?'primary':''}" onclick="hallSetFilter('${v}')">${v}</button>`).join('')}</div><p class="note">Players and coaches wait three years after retirement. Builders become eligible after 20 recorded seasons. Careers begin with your save; earlier accomplishments are not assumed.</p>${people.map(p=>{const s=hallScore(p),peak=Math.max(0,...p.seasons.map(r=>r.peak||0));return `<details class="note"><summary><strong>${escapeHTML(p.name)}</strong> · ${p.kind} · ${escapeHTML(hallSignature(p))} · ${p.inducted!==null?'Class of '+p.inducted:s.pct+'% outlook'} · ${s.awards} achievement points</summary><p>${escapeHTML(p.name)} built a ${p.seasons.length}-season recorded career, most closely associated with ${escapeHTML(hallSignature(p))}. ${p.kind==='Player'?`${s.tot('pts').toLocaleString()} points, ${s.tot('reb').toLocaleString()} rebounds and ${s.tot('ast').toLocaleString()} assists. Peak: ${peak.toFixed(1)} PPG.`:`${s.tot('w')} wins.`} ${s.tot('titles')} championships · ${s.tot('mvp')} MVP · ${s.tot('finalsMvp')} Finals MVP · ${s.tot('dpoy')} DPOY · ${s.tot('coy')} Coach of the Year.</p><p>${p.retired!==null?'Retired '+p.retired+' · Eligible '+(p.retired+3):'Active career'} · ${s.automatic?'Automatic qualification achieved':'Committee threshold: 75%'} · Career WS: ${s.ws===null?'Not tracked':s.ws.toFixed(1)}</p>${p.votes.map(v=>`<p>${v.year} committee vote: ${v.percent}%</p>`).join('')}${hallFranchiseHonors(p).map(v=>`<p>${escapeHTML(v)}</p>`).join('')}${p.inducted!==null?'<blockquote>“This honor belongs to the teammates and coaches who made the journey possible.”</blockquote>':''}</details>`}).join('')||'<p class="note">No careers in this group yet. Completed seasons build the Hall of Fame record.</p>'}<details class="note"><summary>Qualification rules</summary><p>MVP 10 · Finals MVP 8 · Championship 5 · DPOY 5 · Coach of the Year 5 · All-League first team 4 when explicitly recorded. Automatic: 35 points; or two MVPs and two titles; or 15 seasons, 900 games and 20,000 points / 12,000 rebounds / 10,000 assists; or 100 tracked Win Shares. Coaches/builders: 35 points or 15 seasons and 750 wins. Committee voting blends media, former-player and statistical assessments; outlook is a game estimate, not a guarantee.</p></details></section><section class="panel"><div class="panelhead"><h2>Induction ceremonies</h2></div>${[...h.classes].reverse().map(c=>`<p class="note"><strong>Class of ${c.year}</strong> · ${escapeHTML(c.people.map(k=>h.people.find(p=>p.key===k)?.name||'Unknown').join(', ')||'No inductees')}</p>`).join('')||'<p class="note">The first ceremony is held at the next season rollover.</p>'}</section>`}
const hallArchiveBefore=archivePlayoffChampion;archivePlayoffChampion=function(){hallCapture();return hallArchiveBefore()};
const hallNewSeasonBefore=newSeason;newSeason=function(){const year=state.year,result=hallNewSeasonBefore();if(state.year>year){hallRollover();save();render()}return result};
const hallProfileBefore=playerOverview;playerOverview=function(ctx){const recorded=hallState().people.find(p=>p.key==='p:'+ctx.p.id),p=recorded?{...recorded,seasons:recorded.seasons.filter(r=>r.year!==state.year)}:{kind:'Player',seasons:[]},games=state.history.flatMap(g=>g.stage==='Regular season'?g.box.filter(r=>r.playerId===ctx.p.id&&r.mp>0):[]);if(games.length)p.seasons.push({gp:games.length,pts:games.reduce((n,r)=>n+r.pts,0),reb:games.reduce((n,r)=>n+r.reb,0),ast:games.reduce((n,r)=>n+r.ast,0)});const current=p.seasons.at(-1),aw=(state.regularAwards||[]).find(r=>r.year===state.year);if(current&&games.length){current.mvp=aw?.mvp?.name===ctx.p.name?1:0;current.dpoy=aw?.dpoy?.name===ctx.p.name?1:0;}const s=hallScore(p);return hallProfileBefore(ctx)+playerCard('HALL OF FAME OUTLOOK',`<strong>${s.pct}%</strong><meter min="0" max="100" value="${s.pct}"></meter><p>${s.awards} recorded achievement points · ${s.automatic?'Automatic qualifier after retirement waiting period':'Career in progress'}</p>`)};
function readHall(raw,bad){if(raw===undefined)return {version:1,people:[],classes:[]};if(!raw||raw.version!==1||!Array.isArray(raw.people)||!Array.isArray(raw.classes)||raw.people.length>100000)bad('invalid Hall of Fame');for(const p of raw.people){if(typeof p.key!=='string'||typeof p.name!=='string'||p.name.length>150||!['Player','Coach','Builder'].includes(p.kind)||!Array.isArray(p.seasons)||!Array.isArray(p.votes)||![p.retired,p.inducted].every(v=>v===null||Number.isInteger(v)&&v>=1900&&v<=10000))bad('invalid Hall career');for(const r of p.seasons)if(!Number.isInteger(r.year)||typeof r.team!=='string'||Object.entries(r).some(([k,v])=>k!=='team'&&(!Number.isFinite(v)||v<0)))bad('invalid Hall season');for(const v of p.votes)if(!Number.isInteger(v.year)||!Number.isFinite(v.percent)||v.percent<0||v.percent>100)bad('invalid Hall vote')}for(const c of raw.classes)if(!Number.isInteger(c.year)||!Array.isArray(c.people)||c.people.some(k=>!raw.people.some(p=>p.key===k)))bad('invalid Hall class');return JSON.parse(JSON.stringify(raw))}
